import os,json,urllib.request,urllib.error,pathlib,sys,time
ROOT=pathlib.Path(__file__).parent
BASE=os.environ['MCPJAM_API_URL'].rstrip('/')
def call(method,path,body=None,label=None):
 data=None if body is None else json.dumps(body).encode()
 req=urllib.request.Request(BASE+path,data=data,method=method,headers={'Authorization':'Bearer '+os.environ['MCPJAM_API_KEY'],'Content-Type':'application/json'})
 try:
  r=urllib.request.urlopen(req,timeout=20);status=r.status;raw=r.read().decode()
 except urllib.error.HTTPError as e:status=e.code;raw=e.read().decode()
 try:result=json.loads(raw)
 except:result={'raw':raw}
 record={'method':method,'path':path,'request':body,'status':status,'response':result}
 with (ROOT/'requests.jsonl').open('a') as f:f.write(json.dumps(record)+'\n')
 if label:(ROOT/(label+'.json')).write_text(json.dumps(record,indent=2))
 print(json.dumps(record));return result
if __name__=='__main__':call(sys.argv[1],sys.argv[2],json.loads(sys.argv[3]) if len(sys.argv)>3 else None)
PY
